import{_ as r,C as o,o as t,c as s,a5 as i,b as n,w as a,a as l,E as u,a6 as g}from"./chunks/framework.Cx-mnQW-.js";const c="/tauri-plugin-widgets/illustrations/guide.jpg",C=JSON.parse('{"title":"Guide","description":"","frontmatter":{"title":"Guide"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1785753275000}'),p={name:"guide/index.md"};function h(f,e,w,m,_,A){const d=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p><strong>tauri-plugin-widgets</strong> renders home-screen and desktop widgets from one declarative JSON config across Android, iOS, macOS, Windows, and Linux.</p><div class="doc-illust"><p><img src="'+c+'" alt="From one JSON config to native widget surfaces"></p></div><p>App code calls <code>setWidgetConfig</code> → plugin host writes shared storage → native renderers (Glance, WidgetKit, embedded desktop <code>widget.html</code>, Adaptive Cards) read and draw. On desktop you do not install <code>widget.html</code> yourself for the default path — see <a href="/tauri-plugin-widgets/guide/setup/desktop">Desktop webview</a>.</p>',4)),(t(),n(g,null,{default:a(()=>[u(d,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20App%5B%22App%3Cbr%2F%3EsetWidgetConfig%22%5D%20--%3E%20Host%5B%22Rust%20plugin%20host%22%5D%0A%20%20Host%20--%3E%20Store%5B%22Shared%20store%3Cbr%2F%3Econfig%3A%7BwidgetId%7D%22%5D%0A%20%20Store%20--%3E%20G%5B%22Glance%22%5D%0A%20%20Store%20--%3E%20WK%5B%22WidgetKit%22%5D%0A%20%20Store%20--%3E%20HTML%5B%22widget.html%22%5D%0A%20%20Host%20--%3E%20AC%5B%22Adaptive%20Cards%22%5D%20--%3E%20WB%5B%22Widgets%20Board%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>Full diagram + action sequence: <a href="/tauri-plugin-widgets/guide/concepts#architecture-flowchart">Concepts → Architecture flowchart</a>.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><ul><li>Shared <strong>widget IR</strong> (<code>WidgetConfig</code> / <code>WidgetElement</code>) defined in Rust, generated for TypeScript</li><li>Platform backends that map that IR to Glance, SwiftUI, HTML, or Adaptive Cards</li><li>Host APIs for config, key/value data, actions, diagnostics, desktop windows</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><ul><li>A visual designer</li><li>A guarantee that every extended element looks identical everywhere — see <a href="/tauri-plugin-widgets/guide/tiers">Core vs extended</a></li></ul><h2 id="path" tabindex="-1">Path <a class="header-anchor" href="#path" aria-label="Permalink to &quot;Path&quot;">​</a></h2><ol><li><a href="/tauri-plugin-widgets/guide/install">Install</a></li><li><a href="/tauri-plugin-widgets/guide/first-widget">First widget</a> (desktop)</li><li><a href="/tauri-plugin-widgets/guide/concepts">Concepts</a> · <a href="/tauri-plugin-widgets/guide/transport">Transport &amp; signing</a> · <a href="/tauri-plugin-widgets/guide/doctor">Doctor</a></li><li><a href="/tauri-plugin-widgets/guide/setup/">Platform setup</a> when you need a native surface</li><li><a href="/tauri-plugin-widgets/elements/">Elements</a> · <a href="/tauri-plugin-widgets/showcase">Showcase</a></li></ol><p>Contributor docs: <a href="/tauri-plugin-widgets/contributing/">Contributing</a>.</p>',8))])}const b=r(p,[["render",h]]);export{C as __pageData,b as default};
